import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
supplement=pd.read_csv("aoi_visits.csv")
aois=pd.read_csv("aois.csv")

def aoi_service_periods(df,user_df,supplement,aois):
    import matplotlib.dates as mdates
    rows=[]
    for (day,aoi),q in supplement.groupby(['service_date','aoi_id']):
        intervals=sorted((pd.Timestamp(r.arrival_time),pd.Timestamp(r.departure_time)) for r in q.itertuples());merged=[]
        for start,end in intervals:
            if merged and start<=merged[-1][1]:merged[-1][1]=max(merged[-1][1],end)
            else:merged.append([start,end])
        duration=sum((b-a).total_seconds()/60 for a,b in merged)
        rows.append({'service_date':day,'aoi_id':aoi,'periods':len(merged),'union_visit_minutes':duration,
            'task_count':len(df[df.service_date.eq(day)&df.aoi_id.eq(aoi)]),
            'intervals':[[str(a),str(b)] for a,b in merged]})
    d=pd.DataFrame(rows);first=d[d.service_date.eq(d.service_date.min())]
    fig,axes=plt.subplots(1,2,figsize=(11,4.8),constrained_layout=True)
    for i,r in enumerate(first.itertuples()):
        for start,end in r.intervals:
            a=mdates.date2num(pd.Timestamp(start));b=mdates.date2num(pd.Timestamp(end))
            axes[0].barh(i,b-a,left=a,height=.45,color=['#c18b57','#648b9f'][i])
    axes[0].set(yticks=range(len(first)),yticklabels=first.aoi_id,xlabel='Local Shanghai time',title='Actual visit-interval unions on the schema example day')
    axes[0].xaxis_date();axes[0].xaxis.set_major_formatter(mdates.DateFormatter('%H:%M'))
    for aoi,q in d.groupby('aoi_id'):axes[1].scatter(q.task_count,q.periods,label=f'AOI {aoi}',s=70,alpha=.65)
    axes[1].set(xlabel='Pickups per AOI-day',ylabel='Separated service periods',title='Comparable activity, different temporal organization');axes[1].legend()
    return {'aoi_days':len(d),'mean_task_count_by_aoi':d.groupby('aoi_id').task_count.mean().to_dict(),
            'service_period_counts_by_aoi':d.groupby('aoi_id').periods.apply(lambda s:sorted(s.unique().tolist())).to_dict(),'schema_day_intervals':first.to_dict('records')}

evidence=aoi_service_periods(df,user_df,supplement,aois)
print(evidence)
plt.show()
